import numpy as np, forward, time
rng=np.random.default_rng(20240517)
def find_one(u,split,radius=1e6,min_width=1e-6,n_samples=7,rel_tol=1e-12,abs_tol=1e-14):
 fractions=np.linspace(0,1,n_samples+2)[1:-1]
 raw=[]; stack=[(-radius,radius)]
 def lf(t): return forward.forward(t*u)
 while stack:
  a,b=stack.pop(); fa=lf(a); fb=lf(b)
  devs=[abs(lf(a+f*(b-a))-(fa+f*(fb-fa))) for f in fractions]
  tol=rel_tol*max(1.0,abs(fa),abs(fb))+abs_tol
  if max(devs)<=tol: continue
  if b-a<=min_width:
   raw.append((a+b)/2); continue
  m=a+split*(b-a); stack.append((a,m)); stack.append((m,b))
 return sorted(raw)
def find_multi(u,splits=(0.5,0.3819660112501051,0.4142135623730950,0.7071067811865476)):
 allb=[]
 for s in splits: allb.extend(find_one(u,s))
 allb.sort(); out=[]
 for t in allb:
  if not out or t-out[-1]>5e-6: out.append(t)
  else:
   # average duplicates? keep current maybe midpoint
   out[-1]=0.5*(out[-1]+t)
 return out
t0=time.time();bad=0
for li in range(30):
 u=rng.normal(size=10);u/=np.linalg.norm(u)
 br=find_multi(u)
 tb=sorted([-forward.b1[j]/np.dot(forward.A1[j],u) for j in range(20)])
 matched=sum(1 for t in tb if min(abs(t-x) for x in br)<0.01)
 if matched<20: print('BAD',li,len(br),matched)
 bad+= matched<20
print('bad',bad,'time',time.time()-t0)
